SET ANSI_NULLS ON;
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
IF EXISTS (SELECT 1 FROM san_pham WHERE ma_san_pham = 'SP08')
BEGIN
    PRINT N'Đã có dữ liệu bổ sung (SP08), bỏ qua.';
    RETURN;
END
